// Decide (en código, no el modelo) cuál es el siguiente dato a pedir.
// Patrón "slot filling": el estado vive en la ficha del CRM; el modelo solo redacta.
const cfg = $('Configuración del bot').item.json || {};
const ficha = $('Leer ficha').item.json || {};
const nuevos = $('Preparar datos').item.json.nuevos || {};
const lineas = String(ficha.datos || '').split('\n');
const valor = (s) => {
  if (nuevos[s.clave]) return nuevos[s.clave];
  if (s.clave === 'nombre') return String(ficha.nombre || '').trim();
  if (s.clave === 'negocio') return String(ficha.negocio || '').trim();
  const l = lineas.find(x => x.toLowerCase().startsWith(String(s.etiqueta || s.clave).toLowerCase() + ':'));
  return l ? l.slice(l.indexOf(':') + 1).trim() : '';
};
const slots = (cfg.conocer || []).filter(s => s && s.clave);
const ya = slots.filter(s => valor(s)).map(s => (s.etiqueta || s.clave) + ': ' + valor(s));
const faltan = slots.filter(s => !valor(s));
const listo = (s) => (s.requiere || []).every(k => { const r = slots.find(x => x.clave === k); return !r || valor(r); });
const sig = faltan.find(listo) || null;
return { json: { ya: ya.join(' · '), siguiente: sig ? sig.pregunta : '', siguiente_clave: sig ? sig.clave : '', faltan: faltan.map(s => s.clave) } };

// Validador de salida (estilo Guardrails): una sola pregunta por mensaje.
const t = String($json.output || '');
const preguntas = (t.match(/¿[^?]*\?/g) || []).length || (t.match(/\?/g) || []).length;
return { json: { output: t, preguntas } };

// Datos que el modelo extrajo → solo los nuevos o cambiados.
const cfg = $('Configuración del bot').item.json || {};
const ficha = $('Leer ficha').item.json || {};
let ext = {};
try { ext = JSON.parse(($json.choices && $json.choices[0] && $json.choices[0].message.content) || '{}'); } catch (e) { ext = {}; }
const slots = (cfg.conocer || []).filter(s => s && s.clave);
const lineas = String(ficha.datos || '').split('\n');
const actual = (s) => {
  if (s.clave === 'nombre') return String(ficha.nombre || '').trim();
  if (s.clave === 'negocio') return String(ficha.negocio || '').trim();
  const l = lineas.find(x => x.toLowerCase().startsWith(String(s.etiqueta || s.clave).toLowerCase() + ':'));
  return l ? l.slice(l.indexOf(':') + 1).replace(/\(por confirmar\)\s*$/i, '').trim() : '';
};
const nuevos = {};
for (const s of slots) {
  const v = ext[s.clave];
  if (v === undefined || v === null) continue;
  const t = String(v).trim();
  if (!t || t.toLowerCase() === String(actual(s)).toLowerCase()) continue;
  nuevos[s.clave] = t.slice(0, 300);
}
return { json: { nuevos, hay: Object.keys(nuevos).length > 0 } };
